import datetime, html.parser, json, re, sys, urllib.parse, urllib.request

class LinkExtractor(html.parser.HTMLParser):
    def __init__(self):
        super().__init__()
        self.links = []
        self.title_parts = []
        self.text_parts = []
        self.current = None
        self.in_title = False
        self.skip = 0

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        attrs = {k.lower(): v for k, v in attrs if k and v}
        if tag in {'script', 'style', 'noscript'}:
            self.skip += 1
            return
        if tag == 'title':
            self.in_title = True
        if tag == 'a' and attrs.get('href'):
            self.current = {'href': attrs['href'], 'text': []}

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag in {'script', 'style', 'noscript'} and self.skip:
            self.skip -= 1
            return
        if tag == 'title':
            self.in_title = False
        if tag == 'a' and self.current:
            text = clean(' '.join(self.current['text']))
            self.links.append({'href': self.current['href'], 'text': text})
            self.current = None

    def handle_data(self, data):
        if self.skip:
            return
        text = data.strip()
        if not text:
            return
        if self.in_title:
            self.title_parts.append(text)
        if self.current is not None:
            self.current['text'].append(text)
        self.text_parts.append(text)

def clean(value):
    return re.sub(r'\s+', ' ', str(value or '')).strip()

def unwrap_duckduckgo(url):
    parsed = urllib.parse.urlparse(url)
    qs = urllib.parse.parse_qs(parsed.query)
    candidate = qs.get('uddg', [''])[0] or qs.get('u', [''])[0]
    if candidate.startswith(('http://', 'https://')):
        return urllib.parse.unquote(candidate)
    return url

def fetch(url, timeout, max_bytes):
    request = urllib.request.Request(url, headers={'User-Agent': 'MCPStudio-PythonRuntime/1.0 DuckDuckGo link checker'})
    with urllib.request.urlopen(request, timeout=timeout) as response:
        raw = response.read(max_bytes)
        encoding = response.headers.get_content_charset() or 'utf-8'
        return response.geturl(), response.status, response.headers.get('content-type', ''), raw.decode(encoding, errors='replace')

def parse_page(html_text, base_url):
    parser = LinkExtractor()
    parser.feed(html_text)
    title = clean(' '.join(parser.title_parts))
    text = clean(' '.join(parser.text_parts))
    links = []
    seen = set()
    for link in parser.links:
        absolute = urllib.parse.urljoin(base_url, link['href'])
        unwrapped = unwrap_duckduckgo(absolute)
        parsed = urllib.parse.urlparse(unwrapped)
        if parsed.scheme not in {'http', 'https'}:
            continue
        normalized = urllib.parse.urlunparse((parsed.scheme, parsed.netloc, parsed.path, '', parsed.query, ''))
        if normalized in seen:
            continue
        seen.add(normalized)
        links.append({'url': normalized, 'anchorText': link['text']})
    return title, text, links

def is_duckduckgo_result(url):
    host = urllib.parse.urlparse(url).netloc.lower()
    return 'duckduckgo.com' in host

def contains_phrase(*values, phrase):
    needle = phrase.lower()
    return needle in ' '.join(clean(v).lower() for v in values)

def main(params):
    query = params.get('query', 'EoF MCP Studio')
    phrase = params.get('matchPhrase', query)
    timeout = int(params.get('requestTimeoutSeconds', 15))
    max_bytes = int(params.get('maxBytesPerUrl', 350000))
    max_results = int(params.get('maxResults', 10))
    max_text = int(params.get('maxTextCharsPerUrl', 2500))
    search_url = 'https://duckduckgo.com/html/?q=' + urllib.parse.quote_plus(query)

    output = {
        'query': query,
        'matchPhrase': phrase,
        'searchEngine': 'DuckDuckGo HTML',
        'searchUrl': search_url,
        'fetchedAtUTC': datetime.datetime.utcnow().isoformat(timespec='seconds') + 'Z',
        'resultLinks': [],
        'checkedPages': [],
        'hits': []
    }

    final_url, status, content_type, html_text = fetch(search_url, timeout, max_bytes)
    title, text, links = parse_page(html_text, final_url)
    output['searchPage'] = {'finalUrl': final_url, 'statusCode': status, 'contentType': content_type, 'title': title}

    candidates = []
    for link in links:
        url = link['url']
        if is_duckduckgo_result(url) or 'duckduckgo.com/y.js' in url:
            continue
        if url not in [item['url'] for item in candidates]:
            candidates.append(link)
        if len(candidates) >= max_results:
            break
    output['resultLinks'] = candidates

    for link in candidates:
        record = {'url': link['url'], 'anchorText': link.get('anchorText', '')}
        try:
            final, code, ctype, page_html = fetch(link['url'], timeout, max_bytes)
            page_title, page_text, _ = parse_page(page_html, final)
            hit = contains_phrase(link.get('anchorText', ''), link['url'], page_title, page_text, phrase=phrase)
            record.update({
                'finalUrl': final,
                'statusCode': code,
                'contentType': ctype,
                'pageTitle': page_title,
                'containsPhrase': hit,
                'textSample': page_text[:max_text]
            })
            if hit:
                output['hits'].append(record)
        except Exception as exc:
            record.update({'error': f'{type(exc).__name__}: {exc}', 'containsPhrase': False})
        output['checkedPages'].append(record)

    output['hitCount'] = len(output['hits'])
    output['checkedCount'] = len(output['checkedPages'])
    return output

params = json.load(sys.stdin) if not sys.stdin.isatty() else {}
print(json.dumps(main(params), ensure_ascii=False, indent=2))
